/*
========================================================
NODE NAME: LEAD VALIDATION CODE NODE (PRE-LLM)
MODE: Run Once for All Items
========================================================

PURPOSE:
To validate the six required fields of each incoming lead
and determine whether the lead is valid or invalid before
sending it to the next stage of the workflow.

--------------------------------------------------------
1. TASKS THIS NODE PERFORMS
--------------------------------------------------------

1. Receives all incoming lead records.

2. Checks these six required fields:
   - Name
   - Email
   - Service
   - Budget
   - Timeline
   - Requirement

3. Checks whether each required field is empty or contains
   a value.

4. Validates the value and format/content of each field
   according to predefined validation rules.

5. Temporarily trims leading and trailing spaces and
   normalizes text for validation and comparison.
   NOTE: Original field values are not modified.

6. Identifies missing fields and values that fail
   validation rules.

7. Determines the final validation result:
   - All six fields pass validation = Valid Lead
   - One or more fields fail validation = Invalid Lead

8. Adds an "IF node" field:
   - "Valid Lead"
   - "Invalid Lead"

9. Preserves the original lead information and returns
   all processed records to the next workflow node.

10. Preserves item linking information using pairedItem.

--------------------------------------------------------
2. VALIDATION RULES
--------------------------------------------------------

NAME:
Checks for Unicode letters, spaces, apostrophes and
hyphens. Requires at least two letters in each name segment.

EMAIL:
Checks basic email structure, local-part dot placement,
and domain-label formatting using regex.

SERVICE:
Checks whether the requested service matches an
approved service or its accepted alias.

BUDGET:
Rejects empty, unspecified, zero and negative budgets.
Accepts positive numeric USD amounts with up to
two decimal places and correctly grouped commas.

TIMELINE:
Checks whether the timeline matches one of the
predefined accepted timeline options.

REQUIREMENT:
Rejects empty, numeric-only, suspicious or meaningless
text and requires at least three letters.

--------------------------------------------------------
3. WHAT THIS NODE DOES NOT PERFORM
--------------------------------------------------------

- Does not generate Lead IDs.
- Does not remove duplicate leads.
- Does not validate phone numbers.
- Does not validate company or industry information.
- Does not permanently remove extra spaces.
- Does not standardize or correct original field values.
- Does not update Google Sheets or CRM records.
- Does not update Data Validation Status or Validation Notes.
- Does not calculate lead scores.
- Does not perform AI analysis.
- Does not determine commercial lead qualification.
- Does not generate follow-up messages.
- Does not send notifications.

--------------------------------------------------------
4. FINAL OUTPUT
--------------------------------------------------------

Returns every processed lead with its original data
and an additional "IF node" field.

This field allows the downstream IF Node to route
Valid Leads and Invalid Leads into separate branches.

IMPORTANT:
This node performs DATA VALIDATION AND CLASSIFICATION.
It checks whether lead information meets predefined
rules; it does not clean, correct or standardize the
original lead data permanently.

========================================================
*/


// 1. Get all incoming lead records from Google Sheets

const items = $input.all();


// 2. Define helper functions

// Convert a value into a trimmed string
function cleanText(value) {
  if (value === null || value === undefined) {
    return "";
  }

  return String(value).trim();
}


// Normalize text for case-insensitive comparisons
function normalizeText(value) {
  return cleanText(value)
    .toLowerCase()
    .replace(/\s+/g, " ");
}


// Check whether a value is empty
function isEmpty(value) {
  return cleanText(value) === "";
}


// 3. Validate Name

function validateName(value) {
  const name = cleanText(value);

  if (!name) return false;

  // Require at least two letters in each name segment.
  // Allow Unicode letters, spaces, apostrophes and hyphens.
  const namePattern =
    /^(?:\p{L}[\p{L}]*\p{L})(?:[\s'-]+\p{L}[\p{L}]*\p{L})*$/u;

  return namePattern.test(name);
}


// 4. Validate Email

function validateEmail(value) {
  const email = cleanText(value);

  if (!email) return false;

  // Check basic email structure, local-part dot placement,
  // and domain-label formatting.
  const emailPattern =
    /^[A-Z0-9_%+-]+(?:\.[A-Z0-9_%+-]+)*@[A-Z0-9](?:[A-Z0-9-]*[A-Z0-9])?(?:\.[A-Z0-9](?:[A-Z0-9-]*[A-Z0-9])?)+$/i;

  return emailPattern.test(email);
}


// 5. Validate Service

function validateService(value) {
  const service = normalizeText(value);

  if (!service) return false;

  // Accepted service names and their agreed alternatives
  const acceptedServices = new Set([
    "automation",
    "ai automation",
    "business automation",
    "workflow automation",
    "process automation",
    "ai-powered automation",
    "business workflow automation",

    "ai agent",
    "ai agents",
    "ai assistant",
    "intelligent agent",
    "intelligent agents",
    "chatbot",
    "ai chatbot",
    "conversational ai",
    "customer support chatbot",
    "customer service chatbot",

    "agentic ai",
    "autonomous ai",
    "autonomous agent",
    "autonomous agents",
    "multi-agent ai",
    "multi-agent system",
    "multi-agent systems"
  ]);

  return acceptedServices.has(service);
}


// 6. Validate Budget

function validateBudget(value) {
  let budget = cleanText(value);

  if (!budget) return false;

  // These values are not confirmed budgets.
  if (/^(negotiable|not decided|not decided yet|unknown)$/i.test(budget)) {
    return false;
  }

  // Accept USD or assume USD when currency is omitted.
  budget = budget
    .replace(/^USD\s*/i, "")
    .replace(/\s*USD$/i, "")
    .replace(/^\$/, "")
    .trim();

  // Validate comma placement before removing commas.
  // Examples:
  // 5000 = valid
  // 5,000 = valid
  // 50,000.50 = valid
  // 5,,000 = invalid
  // 50,00 = invalid
  const budgetPattern =
    /^(?:\d+|\d{1,3}(?:,\d{3})+)(?:\.\d{1,2})?$/;

  if (!budgetPattern.test(budget)) {
    return false;
  }

  // Remove correctly placed commas.
  budget = budget.replace(/,/g, "");

  const amount = Number(budget);

  return Number.isFinite(amount) && amount > 0;
}


// 7. Validate Timeline

function validateTimeline(value) {
  const timeline = normalizeText(value)
    .replace(/[–—]/g, "-");

  if (!timeline) return false;

  const acceptedTimelines = new Set([
    "immediately",
    "asap",
    "as soon as possible",
    "urgent",

    "within 3 days",
    "3 days",

    "within 1 week",
    "1 week",

    "within 2 weeks",
    "2 weeks",

    "within 1 month",
    "1 month",

    "within 2 months",
    "2 months",

    "within 3 months",
    "3 months",

    "within 6 months",
    "6 months",

    "within 2-3 months",
    "2-3 months",

    "within 3-6 months",
    "3-6 months",

    "flexible"
  ]);

  return acceptedTimelines.has(timeline);
}


// 8. Validate Requirement

function validateRequirement(value) {
  const requirement = normalizeText(value);

  if (!requirement) return false;

  // Reject numeric-only information.
  if (/^[\d\s.,$%+-]+$/.test(requirement)) {
    return false;
  }

  // Reject obvious keyboard/random text.
  // Match whole words instead of arbitrary substrings.
  const meaninglessPatterns = [
    /\basdf\b/i,
    /\bqwerty\b/i,
    /\bzxcv\b/i,
    /\btest\b/i,
    /\bxxxxx\b/i
  ];

  if (meaninglessPatterns.some(pattern =>
    pattern.test(requirement)
  )) {
    return false;
  }

  // Require at least three Unicode letters.
  const letters = requirement.match(/\p{L}/gu) || [];

  return letters.length >= 3;
}


// 9. Validate every lead independently

const results = items.map(item => {

  // Preserve the original lead record.
  const lead = { ...item.json };

  // Collect missing and invalid required fields.
  const errors = [];

  // Required field validation.
  const requiredFields = [
    {
      name: "Name",
      value: lead["Name"],
      validator: validateName
    },
    {
      name: "Email",
      value: lead["Email"],
      validator: validateEmail
    },
    {
      name: "Service",
      value: lead["Service"],
      validator: validateService
    },
    {
      name: "Budget",
      value: lead["Budget"],
      validator: validateBudget
    },
    {
      name: "Timeline",
      value: lead["Timeline"],
      validator: validateTimeline
    },
    {
      name: "Requirement",
      value: lead["Requirement"],
      validator: validateRequirement
    }
  ];

  // Check every required field.
  for (const field of requiredFields) {

    if (isEmpty(field.value)) {
      errors.push(`${field.name} is missing`);
    }

    else if (!field.validator(field.value)) {
      errors.push(`${field.name} is invalid`);
    }
  }


  // 10. Generate the IF node column.

  lead["IF node"] =
    errors.length === 0
      ? "Valid Lead"
      : "Invalid Lead";


  // 11. Return original data plus validation result.

  return {
    json: lead,
    pairedItem: item.pairedItem
  };

});


// 12. Return all validated lead records

return results;

/*
=========================================================
PRE-LLM CODE NODE — CRM DATA STANDARDIZATION & VALIDATION
=========================================================

PURPOSE:
To clean, standardize, validate, and prepare incoming CRM
lead records before sending valid leads for AI qualification.

WHAT THIS NODE DOES:

1. NAME STANDARDIZATION
   - Removes unnecessary spaces.
   - Converts names into proper case.

2. EMAIL VALIDATION
   - Removes extra spaces.
   - Converts emails to lowercase.
   - Checks basic email format.

3. PAKISTANI PHONE NUMBER VALIDATION
   - Accepts supported Pakistani mobile number formats.
   - Converts valid numbers into:
     +92 305 2846732
   - Clears invalid phone numbers and records an error.
   - Phone number is optional.

4. BUDGET STANDARDIZATION & VALIDATION
   - Accepts supported USD formats.
   - Converts valid budgets into a standard format, e.g. $2,500.
   - Rejects PKR and invalid budget values.

5. INDUSTRY & SERVICE STANDARDIZATION
   - Maps recognized industry and service variations
     to their standard names.
   - Flags unsupported services.

6. TIMELINE & OTHER TEXT CLEANING
   - Cleans unnecessary spaces in text fields.
   - Standardizes timeline capitalization.
   - Maps recognized lead sources.
   - Fills Status of Lead when it is missing.

7. CREATED DATE VALIDATION
   - Checks supported date formats.
   - Validates actual calendar dates.
   - Converts valid dates into YYYY-MM-DD format.

8. LEAD ID DUPLICATE HANDLING
   - Checks incoming Lead IDs against CRM records.
   - Preserves the ID belonging to the earliest CRM row.
   - Generates a unique numeric ID for duplicate,
     conflicting, or missing IDs.

9. REQUIRED FIELD VALIDATION
   - Checks Name, Email, Service, Budget, Timeline,
     and Requirement.
   - Records missing required information.

10. VALIDATION REPORTING
    - Sets Data Validation Status to Valid or Invalid.
    - Generates Missing Information.
    - Generates Validation Notes.
    - Preserves the original CRM row number for
      accurate record updates.

OUTPUT:
- Valid records are prepared for the AI qualification path.
- Invalid records contain validation errors and can be
  directed to the manual correction path.

IMPORTANT:
This node performs data cleaning and basic validation.
It does not verify email deliverability, confirm phone
number ownership, or determine whether a lead is genuinely
qualified. AI qualification happens in a later stage.

=========================================================
*/


// ======================================================
// SECTION 1 — STANDARDIZATION MAPS
// ======================================================

const serviceMap = {
  "ai automation": "AI Automation",
  "automation": "AI Automation",
  "ai workflow automation": "AI Automation",
  "workflow automation": "AI Automation",
  "business automation": "AI Automation",
  "business process automation": "AI Automation",
  "process automation": "AI Automation",
  "ai powered automation": "AI Automation",
  "ai-powered automation": "AI Automation",

  "ai agent": "AI Agents",
  "ai agents": "AI Agents",
  "agent": "AI Agents",
  "intelligent agents": "AI Agents",
  "ai assistant": "AI Agents",
  "ai assistants": "AI Agents",
  "chatbot": "AI Agents",
  "chatbots": "AI Agents",
  "ai chatbot": "AI Agents",
  "conversational ai": "AI Agents",

  "agentic ai": "Agentic AI",
  "autonomous ai": "Agentic AI",
  "autonomous agents": "Agentic AI",
  "multi-agent ai": "Agentic AI",
  "multi agent ai": "Agentic AI"
};


const industryMap = {
  "e-commerce": "E-commerce",
  "e commerce": "E-commerce",
  "ecommerce": "E-commerce",
  "online retail": "E-commerce",
  "online shopping": "E-commerce",

  "it": "IT Services",
  "it service": "IT Services",
  "it services": "IT Services",
  "it solutions": "IT Solutions",
  "information technology": "IT Services",
  "software": "IT Services",
  "software development": "IT Services",
  "technology": "IT Services",
  "tech": "IT Services",

  "healthcare": "Healthcare",
  "health care": "Healthcare",
  "medical": "Healthcare",

  "real estate": "Real Estate",
  "property": "Real Estate",
  "construction": "Construction",

  "finance": "Finance",
  "financial services": "Finance",
  "banking": "Finance",
  "accounting": "Finance",
  "insurance": "Finance",

  "education": "Education",
  "e-learning": "Education",

  "manufacturing": "Manufacturing",
  "production": "Manufacturing",

  "logistics": "Logistics",
  "transportation": "Logistics",
  "supply chain": "Logistics",

  "wholesale": "Wholesale",
  "food and beverage": "Food & Beverage",
  "food & beverage": "Food & Beverage",
  "restaurant": "Food & Beverage",
  "hospitality": "Hospitality",
  "tourism": "Hospitality",

  "marketing": "Marketing",
  "advertising": "Marketing",
  "digital marketing": "Marketing",

  "media": "Media & Design",
  "design": "Media & Design",
  "graphic design": "Media & Design",

  "professional services": "Professional Services",
  "consulting": "Consulting",
  "agriculture": "Agriculture",
  "farming": "Agriculture",
  "automotive": "Automotive",
  "retail": "Retail",
  "food delivery": "Food Delivery",
  "design agency": "Design Agency",
  "travel": "Travel"
};


const sourceMap = {
  "linkedin": "LinkedIn",
  "whatsapp": "WhatsApp",
  "facebook": "Facebook",
  "instagram": "Instagram",
  "website": "Website",
  "website form": "Website Form",
  "referral": "Referral",
  "email": "Email",
  "cold call": "Cold Call"
};


// ======================================================
// SECTION 2 — HELPER FUNCTIONS
// ======================================================

function cleanText(value) {

  if (value === null || value === undefined) {
    return "";
  }

  return String(value)
    .trim()
    .replace(/\s+/g, " ");
}


function toProperCase(value) {

  return cleanText(value)
    .toLowerCase()
    .replace(/\b\w/g, char => char.toUpperCase());
}


// ======================================================
// SECTION 3 — COLLECT CRM AND INCOMING LEAD IDs
// ======================================================

const items = $input.all();

const crmRows = $('Fetch CRM Leads').all();

const crmIDMap = new Map();


// Collect every existing CRM ID with its row number.

for (const row of crmRows) {

  const id = cleanText(row.json["Lead ID"]).toUpperCase();

  const rowNumber = Number(row.json.row_number);

  if (!id) continue;

  if (!crmIDMap.has(id)) {
    crmIDMap.set(id, []);
  }

  crmIDMap.get(id).push(rowNumber);

}


// Sort row numbers so the earliest existing record
// keeps its original ID when a genuine duplicate exists.

for (const [id, rows] of crmIDMap.entries()) {

  rows.sort((a, b) => a - b);

}


// Store all IDs so generated IDs cannot collide
// with existing CRM IDs or incoming IDs.

const usedIDs = new Set(crmIDMap.keys());


for (const item of items) {

  const id = cleanText(item.json["Lead ID"]).toUpperCase();

  if (id) {
    usedIDs.add(id);
  }

}


// Track IDs already processed in this execution.

const seenIDs = new Set();


// ======================================================
// SECTION 4 — GENERATE UNIQUE 12-DIGIT LEAD IDs
// ======================================================

function generateUniqueID() {

  let newID;

  do {

    newID = String(
      Math.floor(100000000000 + Math.random() * 900000000000)
    );

  } while (usedIDs.has(newID));

  usedIDs.add(newID);

  return newID;
}


// ======================================================
// SECTION 5 — PROCESS EACH LEAD
// ======================================================

for (const item of items) {

  const data = item.json;

  const errors = [];

  const missingFields = [];


  // ====================================================
  // SECTION 6 — NAME, EMAIL AND PHONE STANDARDIZATION
  // ====================================================


  // NAME STANDARDIZATION

  data.Name = toProperCase(data.Name);


  // EMAIL STANDARDIZATION

  data.Email = String(data.Email ?? "")
    .trim()
    .toLowerCase();


  // PAKISTAN PHONE NUMBER STANDARDIZATION

  const phone = cleanText(data.Phone);

  if (phone) {

    let digits = phone.replace(/\D/g, "");

    if (digits.startsWith("03") && digits.length === 11) {
      digits = "92" + digits.slice(1);
    }

    else if (digits.startsWith("3") && digits.length === 10) {
      digits = "92" + digits;
    }

    if (/^923\d{9}$/.test(digits)) {

      data.Phone = `+92 ${digits.slice(2, 5)} ${digits.slice(5)}`;

    } else {

      data.Phone = "";

      errors.push("Invalid Pakistani mobile number");

    }

  } else {

    data.Phone = "";

  }


  // ====================================================
  // SECTION 7 — INDUSTRY AND SERVICE STANDARDIZATION
  // ====================================================


  // INDUSTRY

  const industry = cleanText(data.Industry);

  const industryKey = industry.toLowerCase();

  data.Industry = industryMap[industryKey] || industry;


  // SERVICE

  const service = cleanText(data.Service);

  const serviceKey = service.toLowerCase();


  if (serviceMap[serviceKey]) {

    data.Service = serviceMap[serviceKey];

  } else {

    data.Service = service;

    if (service) {
      errors.push("Unsupported service");
    }

  }


  // ====================================================
  // SECTION 8 — BUDGET STANDARDIZATION AND VALIDATION
  // ====================================================

  const originalBudget = cleanText(data.Budget);

  let budgetText = originalBudget;


  // Reject Pakistani Rupees.

  const isPKR =
    /\bPKR\b|\bRs\.?\b|₨/i.test(budgetText);


  if (!isPKR) {

    // Accept USD prefix, dollar symbol or USD suffix.

    budgetText = budgetText
      .replace(/^\s*USD\s*/i, "")
      .replace(/^\s*\$\s*/, "")
      .replace(/\s*USD\s*$/i, "")
      .trim();

  }


  // Accept:
  // 2500
  // 2,500
  // 1,777,000
  // 2500.50
  // 2,500.50

  const validBudgetFormat =
    /^(?:\d+|\d{1,3}(?:,\d{3})+)(?:\.\d{1,2})?$/.test(budgetText);


  const budgetAmount = validBudgetFormat
    ? Number(budgetText.replace(/,/g, ""))
    : NaN;


  const budgetIsValid =
    !isPKR &&
    validBudgetFormat &&
    Number.isFinite(budgetAmount) &&
    budgetAmount > 0;


  if (budgetIsValid) {

    // Standardize USD budget with comma separators.

    data.Budget = "$" + budgetAmount.toLocaleString("en-US", {

      minimumFractionDigits:
        Number.isInteger(budgetAmount) ? 0 : 2,

      maximumFractionDigits: 2

    });

  }

  else if (originalBudget) {

    if (isPKR) {

      errors.push("Budget must be in USD, not PKR");

    } else {

      errors.push("Budget must be a valid positive USD amount");

    }

    data.Budget = originalBudget;

  }

  else {

    data.Budget = "";

  }


  // ====================================================
  // SECTION 9 — OTHER FIELD STANDARDIZATION
  // ====================================================


  // TIMELINE

  data.Timeline = toProperCase(data.Timeline);


  // REQUIREMENT

  data.Requirement = cleanText(data.Requirement);


  // COMPANY

  data.Company = cleanText(data.Company);


  // SOURCE

  const source = cleanText(data.Source);

  const sourceKey = source.toLowerCase();

  data.Source = sourceMap[sourceKey] || source;





  // ====================================================
  // SECTION 10 — CREATED DATE STANDARDIZATION
  // ====================================================

  const originalDate = cleanText(data["Created Date"]);


  if (originalDate) {

    let year;

    let month;

    let day;

    let match;


    // FORMAT: YYYY-MM-DD

    match = originalDate.match(
      /^(\d{4})-(\d{2})-(\d{2})$/
    );


    if (match) {

      year = Number(match[1]);

      month = Number(match[2]);

      day = Number(match[3]);

    }


    // FORMAT: DD/MM/YYYY

    else if (
      (match = originalDate.match(
        /^(\d{2})\/(\d{2})\/(\d{4})$/
      ))
    ) {

      day = Number(match[1]);

      month = Number(match[2]);

      year = Number(match[3]);

    }


    // FORMAT: YYYY/MM/DD

    else if (
      (match = originalDate.match(
        /^(\d{4})\/(\d{2})\/(\d{2})$/
      ))
    ) {

      year = Number(match[1]);

      month = Number(match[2]);

      day = Number(match[3]);

    }


    // DATE VALIDATION

    if (
      year !== undefined &&
      year >= 1000 &&
      month >= 1 &&
      month <= 12
    ) {

      const isLeapYear =
        year % 400 === 0 ||
        (year % 4 === 0 && year % 100 !== 0);


      const daysInMonth = [

        31,

        isLeapYear ? 29 : 28,

        31,

        30,

        31,

        30,

        31,

        31,

        30,

        31,

        30,

        31

      ];


      if (
        day >= 1 &&
        day <= daysInMonth[month - 1]
      ) {

        data["Created Date"] =
          `${year}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;

      } else {

        errors.push("Invalid Created Date");

      }

    } else {

      errors.push("Invalid Created Date");

    }

  } else {

    data["Created Date"] = "";

  }


  // ====================================================
  // SECTION 11 — REQUIRED FIELD VALIDATION
  // ====================================================

  const requiredFields = [

    "Name",

    "Email",

    "Service",

    "Budget",

    "Timeline",

    "Requirement"

  ];


  for (const field of requiredFields) {

    if (!cleanText(data[field])) {

      missingFields.push(field);

      errors.push(`${field} is missing`);

    }

  }


  // ====================================================
  // SECTION 12 — NAME AND TIMELINE VALIDATION
  // ====================================================


  // NAME VALIDATION

  const nameRegex =
    /^[\p{L}\p{M}][\p{L}\p{M}\s.'’-]*$/u;


  if (
    data.Name &&
    !nameRegex.test(data.Name)
  ) {

    errors.push("Invalid name format");

  }


  // TIMELINE VALIDATION

  if (
    data.Timeline &&
    !/\p{L}/u.test(data.Timeline)
  ) {

    errors.push("Invalid timeline format");

  }


  // ====================================================
  // SECTION 13 — EMAIL VALIDATION
  // ====================================================

  const emailRegex =
    /^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$/;


  if (data.Email) {

    if (/\s/.test(data.Email)) {

      errors.push("Email contains internal whitespace");

    }

    else if (!emailRegex.test(data.Email)) {

      errors.push("Invalid email format");

    }

  }


  // ====================================================
  // SECTION 14 — CORRECTED LEAD ID PRESERVATION
  // ====================================================

  const originalID = cleanText(data["Lead ID"]);

  const normalizedID = originalID.toUpperCase();

  const currentRowNumber = Number(data.row_number);

  const existingRecords =
    normalizedID
      ? crmIDMap.get(normalizedID) || []
      : [];


  // Find the earliest CRM row that currently owns this ID.

  const firstExistingRow = existingRecords.length > 0
    ? existingRecords[0]
    : null;


  // Determine whether the ID belongs to this exact row.

  const belongsToCurrentRow =
    Number.isFinite(currentRowNumber) &&
    firstExistingRow === currentRowNumber;


  // Check whether this ID has already been used
  // by another incoming record in this execution.

  const duplicateInIncoming =
    normalizedID && seenIDs.has(normalizedID);


  if (!originalID) {

    // No original ID: generate a new unique ID.

    data["Lead ID"] = generateUniqueID();

    data["Lead ID Status"] = "Generated";

    seenIDs.add(data["Lead ID"].toUpperCase());

  }

  else if (
    belongsToCurrentRow &&
    !duplicateInIncoming
  ) {

    // Original ID belongs to this same CRM row.
    // Preserve it without replacing it.

    data["Lead ID"] = originalID;

    data["Lead ID Status"] = "Valid";

    seenIDs.add(normalizedID);

  }

  else if (
    existingRecords.length === 0 &&
    !duplicateInIncoming
  ) {

    // ID does not exist in CRM or earlier incoming items.
    // Preserve this unique original ID.

    data["Lead ID"] = originalID;

    data["Lead ID Status"] = "Valid";

    usedIDs.add(normalizedID);

    seenIDs.add(normalizedID);

  }

  else {

    // Existing ID belongs to another CRM row or has
    // already appeared in the incoming batch.
    // Generate a replacement ID.

    data["Lead ID"] = generateUniqueID();

    data["Lead ID Status"] = "Duplicate Replaced";

    seenIDs.add(data["Lead ID"].toUpperCase());

  }


  // ====================================================
  // SECTION 15 — FINAL VALIDATION RESULTS
  // ====================================================

  data["Missing Information"] =

    missingFields.length > 0

      ? missingFields.join(", ")

      : "None";


  data["Data Validation Status"] =

    errors.length === 0

      ? "Valid"

      : "Invalid";


  data["Validation Notes"] =

    errors.length === 0

      ? "All validation checks passed"

      : errors.join("; ");

}


// ======================================================
// SECTION 16 — RETURN ALL PROCESSED LEADS
// ======================================================

return items;

/*
POST-LLM CODE NODE
Mode: Run Once for All Items

Responsibilities:
1. Parse and validate the exact 31-field AI schema.
2. Match AI records with original CRM records.
3. Classify final Urgency using CRM and LLM evidence.
4. Recalculate deterministic scoring.
5. Apply qualification and next-action rules.
6. Generate Recommended Action from final Next Action Type.
7. Preserve original CRM fields.
8. Return corrected CRM records.

Duplicate detection has been removed.
The CRM is responsible for preventing duplicate leads.
Unique Lead ID validation is retained.
*/

const QUALIFICATION_THRESHOLD = 70;

const AI_COMPONENT_MAX_POINTS = {
  Purchase_Intent_Points: 25,
  Business_Need_Points: 15,
};

const ALLOWED_NEXT_ACTIONS = [
  "Contact Immediately",
  "Schedule Meeting",
  "Send Pricing Information",
  "Request More Information",
  "Follow Up Later",
  "Do Not Pursue",
];

const AI_REQUIRED_FIELDS = [
  "Lead_id",
  "row_number",
  "Client_name",
  "Company",
  "Service",
  "Urgency",
  "Budget",
  "Estimated_Project_Price",
  "Budget_suitability",
  "Business_need",
  "Purchase_intent",
  "Qualification_reasoning",
  "AI_Analysis",
  "Service_Fit",
  "Timeline_Clarity",
  "Budget_Points",
  "Purchase_Intent_Points",
  "Urgency_Points",
  "Business_Need_Points",
  "Service_Fit_Points",
  "Timeline_Points",
  "Total_Lead_Score",
  "Score_Explanation",
  "Lead_Category",
  "Qualification_Status",
  "Qualification_Reason",
  "Recommended_Action",
  "Next_Action_Type",
  "Follow_Up_Message",
  "Priority",
  "Data_Validation_Status",
];

// --------------------------------------------------
// 1. GENERAL HELPERS
// --------------------------------------------------

function normalizeId(value) {
  if (value === null || value === undefined) return "";
  return String(value).trim();
}

function cleanText(value) {
  if (value === null || value === undefined) return "";
  return String(value).trim();
}

function normalizeComparable(value) {
  return cleanText(value)
    .toLowerCase()
    .replace(/\s+/g, " ")
    .trim();
}

function parseNumber(value) {
  if (value === null || value === undefined || value === "") {
    return null;
  }

  if (typeof value === "number") {
    return Number.isFinite(value) ? value : null;
  }

  const cleaned = String(value).replace(/[$,\s]/g, "");
  const parsed = Number(cleaned);

  return Number.isFinite(parsed) ? parsed : null;
}

function parseJsonString(value) {
  if (typeof value !== "string") return null;

  let text = value.trim();

  text = text
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/, "")
    .trim();

  try {
    return JSON.parse(text);
  } catch (error) {
    return null;
  }
}

function isValidEmail(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(cleanText(email));
}

function isNonEmpty(value) {
  return (
    value !== null &&
    value !== undefined &&
    String(value).trim() !== ""
  );
}

function clampInteger(value, min, max, fieldName) {
  const number = parseNumber(value);

  if (
    number === null ||
    !Number.isInteger(number) ||
    number < min ||
    number > max
  ) {
    throw new Error(
      `${fieldName} must be an integer between ${min} and ${max}. Received: ${value}`
    );
  }

  return number;
}

// --------------------------------------------------
// 2. STRICT AI SCHEMA VALIDATION
// --------------------------------------------------

function validateAISchema(ai, leadId) {
  if (!ai || typeof ai !== "object" || Array.isArray(ai)) {
    throw new Error(
      `Invalid AI record for ${leadId}. Expected an object.`
    );
  }

  const actualFields = Object.keys(ai);

  const missingFields = AI_REQUIRED_FIELDS.filter(
    field => !actualFields.includes(field)
  );

  const extraFields = actualFields.filter(
    field => !AI_REQUIRED_FIELDS.includes(field)
  );

  if (missingFields.length || extraFields.length) {
    throw new Error(
      `AI schema mismatch for ${leadId}. ` +
      `Missing fields: ${missingFields.join(", ") || "None"}. ` +
      `Extra fields: ${extraFields.join(", ") || "None"}.`
    );
  }
}

// --------------------------------------------------
// 3. GET ORIGINAL CRM RECORDS
// --------------------------------------------------

const originalItems = $("Aggregate Valid Leads").all();

const originalRecords = originalItems.flatMap(item => {
  const data = item.json;

  if (Array.isArray(data.Leads)) {
    return data.Leads;
  }

  return [data];
});

if (!originalRecords.length) {
  throw new Error(
    "No original CRM records found in Aggregate node."
  );
}

const originalMap = new Map();

for (const original of originalRecords) {
  const id = normalizeId(original["Lead ID"]);

  if (!id) {
    throw new Error(
      `An original CRM record has a missing Lead ID. ` +
      `Row: ${original.row_number ?? "Unknown"}`
    );
  }

  if (originalMap.has(id)) {
    throw new Error(
      `Duplicate Lead ID found in original CRM: ${id}`
    );
  }

  originalMap.set(id, original);
}

// --------------------------------------------------
// 4. EXTRACT AI OUTPUT
// --------------------------------------------------

const inputItems = $input.all();

if (!inputItems.length) {
  throw new Error(
    "No AI output received by the Post-Code node."
  );
}

function extractAIRecords(items) {
  const extracted = [];

  for (const item of items) {
    const data = item.json;

    if (Array.isArray(data)) {
      extracted.push(...data);
      continue;
    }

    if (Array.isArray(data.Leads)) {
      extracted.push(...data.Leads);
      continue;
    }

    if (Array.isArray(data.leads)) {
      extracted.push(...data.leads);
      continue;
    }

    if (
      data.Lead_id !== undefined ||
      data.Lead_ID !== undefined
    ) {
      extracted.push(data);
      continue;
    }

    const possibleTextFields = [
      "text",
      "output",
      "response",
      "message",
    ];

    let parsed = null;

    for (const field of possibleTextFields) {
      if (data[field] === undefined) continue;

      if (typeof data[field] === "string") {
        parsed = parseJsonString(data[field]);
      } else if (
        data[field] &&
        typeof data[field] === "object"
      ) {
        parsed = data[field];
      }

      if (parsed) break;
    }

    if (parsed) {
      if (Array.isArray(parsed)) {
        extracted.push(...parsed);
      } else if (Array.isArray(parsed.Leads)) {
        extracted.push(...parsed.Leads);
      } else if (Array.isArray(parsed.leads)) {
        extracted.push(...parsed.leads);
      } else {
        extracted.push(parsed);
      }

      continue;
    }

    throw new Error(
      "Unable to extract AI lead records from the current input. " +
      "Expected an array, Leads array, or JSON in text/output/response/message."
    );
  }

  return extracted;
}

const aiRecords = extractAIRecords(inputItems);

if (!aiRecords.length) {
  throw new Error(
    "The AI output contains no lead records."
  );
}

// --------------------------------------------------
// 5. VERIFY RECORD COUNTS
// --------------------------------------------------

if (aiRecords.length !== originalRecords.length) {
  throw new Error(
    `Record count mismatch. Original CRM: ${originalRecords.length}; ` +
    `AI output: ${aiRecords.length}.`
  );
}

// --------------------------------------------------
// 6. DETERMINISTIC SCORING FUNCTIONS
// --------------------------------------------------

function calculateBudgetPoints(budget, estimatedPrice) {
  if (
    budget === null ||
    estimatedPrice === null ||
    estimatedPrice <= 0
  ) {
    return 0;
  }

  const ratio = budget / estimatedPrice;

  if (ratio >= 1.20) return 20;
  if (ratio >= 1.00) return 17;

  const shortfall = (1 - ratio) * 100;

  if (shortfall <= 10) return 15;
  if (shortfall <= 20) return 12;
  if (shortfall <= 30) return 8;
  if (shortfall <= 50) return 4;

  return 0;
}

// --------------------------------------------------
// 7. URGENCY CLASSIFICATION
// --------------------------------------------------

function classifyFinalUrgency(original, ai) {

  // Preserve valid human-entered CRM urgency.
  const originalUrgency = normalizeComparable(
    original.Urgency
  );

  if (originalUrgency === "high") return "High";
  if (originalUrgency === "medium") return "Medium";
  if (originalUrgency === "low") return "Low";

  // Collect original CRM and LLM evidence.
  const requirementText = normalizeComparable(
    original.Requirement
  );

  const supportingText = normalizeComparable(
    cleanText(ai.Business_need) + " " +
    cleanText(ai.Purchase_intent) + " " +
    cleanText(ai.AI_Analysis)
  );

  const combinedText =
    requirementText + " " + supportingText;

  const timelineText = normalizeComparable(
    original.Timeline
  );

  // No requirement means insufficient evidence.
  if (!requirementText) {
    return null;
  }

  // HIGH: explicit urgent or critical evidence.
  const highPatterns = [
    /\burgent\b/,
    /\burgently\b/,
    /\bcritical\b/,
    /\bemergency\b/,
    /\basap\b/,
    /\bimmediately\b/,
    /\bright away\b/,
    /\bat once\b/,
    /\bwithout delay\b/,
    /\btime sensitive\b/,
    /\btime-critical\b/,
    /\bdeadline (is )?today\b/,
    /\bdeadline (is )?tomorrow\b/,
    /\bwithin 24 hours\b/,
    /\bwithin 48 hours\b/,
    /\bproduction (is )?down\b/,
    /\bsystem (is )?down\b/,
    /\boperations (are )?stopped\b/,
    /\bbusiness (is )?stopped\b/,
    /\bcurrently losing customers\b/,
    /\bcurrently losing revenue\b/
  ];

  if (
    highPatterns.some(pattern =>
      pattern.test(requirementText)
    )
  ) {
    return "High";
  }

  // MEDIUM: explicit near-term pressure.
  const mediumPatterns = [
    /\bsoon\b/,
    /\bnear term\b/,
    /\bnear-term\b/,
    /\bhigh priority\b/,
    /\bmedium priority\b/,
    /\bpriority requirement\b/,
    /\bwithin the next few days\b/,
    /\bwithin the next few weeks\b/,
    /\bin the coming weeks\b/,
    /\bupcoming deadline\b/,
    /\bneed this shortly\b/,
    /\bpreferably soon\b/
  ];

  const explicitMediumEvidence =
    mediumPatterns.some(pattern =>
      pattern.test(combinedText)
    );

  // Timeline is supporting evidence, not a substitute
  // for a meaningful business requirement.
  const nearTermTimelinePatterns = [
    /\bwithin\s+[1-9]\s*days?\b/,
    /\bwithin\s+1\s*week\b/,
    /\bwithin\s+2\s*weeks\b/,
    /\bin\s+[1-9]\s*days?\b/,
    /\bin\s+1\s*week\b/,
    /\bin\s+2\s*weeks\b/,
    /\bnext\s+week\b/
  ];

  const nearTermTimeline =
    nearTermTimelinePatterns.some(pattern =>
      pattern.test(timelineText)
    );

  const immediateTimelinePatterns = [
    /\bimmediately\b/,
    /\bright away\b/,
    /\basap\b/,
    /\bat once\b/,
    /\bwithout delay\b/,
    /\bstarting now\b/
  ];

  const immediateTimeline =
    immediateTimelinePatterns.some(pattern =>
      pattern.test(timelineText)
    );

  const meaningfulLLMNeed =
    cleanText(ai.Business_need).length > 20 ||
    cleanText(ai.Purchase_intent).length > 20;

  if (
    explicitMediumEvidence ||
    ((nearTermTimeline || immediateTimeline) && meaningfulLLMNeed)
  ) {
    return "Medium";
  }

  // LOW: explicitly flexible or non-urgent.
  const lowPatterns = [
    /\bno rush\b/,
    /\bnot urgent\b/,
    /\bnon urgent\b/,
    /\bnot time sensitive\b/,
    /\bflexible deadline\b/,
    /\bflexible timeline\b/,
    /\bwhenever convenient\b/,
    /\bno immediate requirement\b/,
    /\bjust exploring\b/,
    /\bexploring options\b/,
    /\bfor future consideration\b/,
    /\bno fixed deadline\b/
  ];

  if (
    lowPatterns.some(pattern =>
      pattern.test(combinedText)
    )
  ) {
    return "Low";
  }

  // Insufficient evidence: do not guess.
  return null;
}

function calculateUrgencyPoints(finalUrgency) {
  const urgency = normalizeComparable(finalUrgency);

  if (urgency === "high") return 15;
  if (urgency === "medium") return 10;
  if (urgency === "low") return 5;

  return 0;
}

// --------------------------------------------------
// 8. SERVICE FIT AND TIMELINE SCORING
// --------------------------------------------------

function normalizeServiceFit(value) {
  const fit = normalizeComparable(value);

  if (fit === "strong match") return "Strong Match";
  if (fit === "partial match") return "Partial Match";
  if (fit === "uncertain") return "Uncertain";
  if (fit === "no match") return "No Match";

  throw new Error(
    `Invalid Service_Fit value: ${value}`
  );
}

function calculateServiceFitPoints(serviceFit) {
  switch (serviceFit) {
    case "Strong Match":
      return 15;
    case "Partial Match":
      return 10;
    case "Uncertain":
      return 5;
    case "No Match":
      return 0;
    default:
      return 0;
  }
}

function calculateTimelinePoints(originalTimeline) {
  const timeline = normalizeComparable(originalTimeline);

  if (!timeline) return 0;

  const immediatePatterns = [
    /\bimmediately\b/,
    /\bright away\b/,
    /\basap\b/,
    /\bat once\b/,
    /\bwithout delay\b/,
    /\bstarting now\b/,
  ];

  if (
    immediatePatterns.some(pattern =>
      pattern.test(timeline)
    )
  ) {
    return 10;
  }

  const exactDatePatterns = [
    /\b\d{4}-\d{1,2}-\d{1,2}\b/,
    /\b\d{1,2}[/-]\d{1,2}[/-]\d{2,4}\b/,
    /\b\d{1,2}\s+(jan|january|feb|february|mar|march|apr|april|may|jun|june|jul|july|aug|august|sep|september|oct|october|nov|november|dec|december)\b/,
  ];

  if (
    exactDatePatterns.some(pattern =>
      pattern.test(timeline)
    )
  ) {
    return 10;
  }

  const generalPatterns = [
    /\bwithin\s+\d+\s*(day|days|week|weeks|month|months)\b/,
    /\bin\s+\d+\s*(day|days|week|weeks|month|months)\b/,
    /\bthis\s+(week|month|quarter|year)\b/,
    /\bnext\s+(week|month|quarter|year)\b/,
    /\b\d+\s*(day|days|week|weeks|month|months)\b/,
  ];

  if (
    generalPatterns.some(pattern =>
      pattern.test(timeline)
    )
  ) {
    return 7;
  }

  const vaguePatterns = [
    /\bsoon\b/,
    /\blater\b/,
    /\bsomeday\b/,
    /\bnot sure\b/,
    /\bwhen possible\b/,
    /\bflexible\b/,
    /\bto be decided\b/,
    /\bnot decided\b/,
    /\bno timeline\b/,
  ];

  if (
    vaguePatterns.some(pattern =>
      pattern.test(timeline)
    )
  ) {
    return 3;
  }

  return 0;
}


// --------------------------------------------------
// GENERATE TIMELINE CLARITY — DETERMINISTIC RULES
// --------------------------------------------------

function generateTimelineClarity(originalTimeline) {

  let timeline = cleanText(originalTimeline)
    .toLowerCase()
    .replace(/[–—]/g, "-");

  // 1. Missing timeline
  if (!timeline) {
    return "Missing or unclear";
  }

  // 2. Flexible timeline
  const flexiblePatterns = [
    /\bflexible\b/,
    /\bno rush\b/,
    /\bwhenever convenient\b/,
    /\bno fixed deadline\b/,
    /\bflexible deadline\b/,
    /\bflexible timeline\b/,
    /\bno immediate requirement\b/
  ];

  if (flexiblePatterns.some(pattern => pattern.test(timeline))) {
    return "Flexible";
  }

  // 3. Immediate requirements
  const immediatePatterns = [
    /\bimmediately\b/,
    /\basap\b/,
    /\bas soon as possible\b/,
    /\bright away\b/,
    /\bat once\b/,
    /\bwithout delay\b/,
    /\burgent\b/,
    /\burgently\b/
  ];

  if (immediatePatterns.some(pattern => pattern.test(timeline))) {
    return "Short-term";
  }

  // Convert durations into days.
  function convertToDays(value, unit) {

    if (unit.startsWith("day")) return value;
    if (unit.startsWith("week")) return value * 7;
    if (unit.startsWith("month")) return value * 30;
    if (unit.startsWith("year")) return value * 365;

    return null;
  }

  // 4. Numeric ranges: use the upper end of the range.
  // Examples: 2-3 weeks, 1-2 months.

  const rangePattern =
    /\b(\d+(?:\.\d+)?)\s*(?:-|to)\s*(\d+(?:\.\d+)?)\s*(days?|weeks?|months?|years?)\b/;

  const rangeMatch = timeline.match(rangePattern);

  if (rangeMatch) {

    const upperValue = Number(rangeMatch[2]);
    const unit = rangeMatch[3];

    const days = convertToDays(upperValue, unit);

    if (days <= 7) return "Short-term";
    if (days <= 30) return "Medium-term";

    return "Long-term";
  }

  // 5. Numeric durations.
  // Examples: within 3 days, in 2 weeks, 3 months.

  const durationPattern =
    /\b(\d+(?:\.\d+)?)\s*(days?|weeks?|months?|years?)\b/;

  const durationMatch = timeline.match(durationPattern);

  if (durationMatch) {

    const value = Number(durationMatch[1]);
    const unit = durationMatch[2];

    const days = convertToDays(value, unit);

    if (days <= 7) return "Short-term";
    if (days <= 30) return "Medium-term";

    return "Long-term";
  }

  // 6. Written duration expressions.

  const shortTermPatterns = [
    /\bwithin a week\b/,
    /\bin a week\b/,
    /\bnext week\b/,
    /\bnext few days\b/
  ];

  if (shortTermPatterns.some(pattern => pattern.test(timeline))) {
    return "Short-term";
  }

  const mediumTermPatterns = [
    /\bwithin a month\b/,
    /\bin a month\b/,
    /\bnext month\b/,
    /\bnext few weeks\b/
  ];

  if (mediumTermPatterns.some(pattern => pattern.test(timeline))) {
    return "Medium-term";
  }

  const longTermPatterns = [
    /\bnext few months\b/,
    /\bnext year\b/
  ];

  if (longTermPatterns.some(pattern => pattern.test(timeline))) {
    return "Long-term";
  }

  // 7. Unrecognized or ambiguous timelines.
  return "Needs review";
}


// --------------------------------------------------
// 9. CATEGORY / QUALIFICATION / PRIORITY
// --------------------------------------------------

function calculateLeadCategory(score) {
  if (score >= 80) return "Hot";
  if (score >= 60) return "Warm";
  if (score >= 40) return "Cold";

  return "Unqualified";
}

function calculateQualification(
  score,
  category,
  validationStatus,
  serviceFit
) {
  return (
    score >= QUALIFICATION_THRESHOLD &&
    ["Hot", "Warm"].includes(category) &&
    normalizeComparable(validationStatus) === "valid" &&
    serviceFit !== "No Match"
  )
    ? "Qualified"
    : "Unqualified";
}

function calculatePriority(
  qualificationStatus,
  category
) {
  if (qualificationStatus !== "Qualified") {
    return "Low";
  }

  if (category === "Hot") return "High";
  if (category === "Warm") return "Medium";

  return "Low";
}

function calculateBudgetSuitability(budgetPoints) {
  return budgetPoints >= 15
    ? "Suitable"
    : "Not Suitable";
}

// --------------------------------------------------
// 10. MISSING INFORMATION CHECK
// --------------------------------------------------

function hasMissingInformation(original) {
  const missing = normalizeComparable(
    original["Missing Information"]
  );

  return (
    missing !== "" &&
    missing !== "none" &&
    missing !== "no" &&
    missing !== "n/a" &&
    missing !== "not applicable"
  );
}

// --------------------------------------------------
// 11. NEXT ACTION RULES
// --------------------------------------------------

function determineNextAction(
  ai,
  qualificationStatus,
  serviceFit,
  missingInformation,
  finalUrgency
) {
  const aiAction = cleanText(ai.Next_Action_Type);

  if (!ALLOWED_NEXT_ACTIONS.includes(aiAction)) {
    throw new Error(
      `Invalid Next_Action_Type for ${ai.Lead_id}: ${aiAction}`
    );
  }

  if (serviceFit === "No Match") {
    return "Do Not Pursue";
  }

  if (qualificationStatus !== "Qualified") {
    if (missingInformation) {
      return "Request More Information";
    }

    return "Follow Up Later";
  }

  if (aiAction === "Do Not Pursue") {
    return "Follow Up Later";
  }

  if (aiAction === "Contact Immediately") {
    const intentPoints = clampInteger(
      ai.Purchase_Intent_Points,
      0,
      25,
      "Purchase_Intent_Points"
    );

    const urgency = normalizeComparable(finalUrgency);

    if (
      intentPoints >= 20 &&
      urgency === "high"
    ) {
      return "Contact Immediately";
    }

    return "Schedule Meeting";
  }

  if (aiAction === "Send Pricing Information") {
    const quoteRequested =
      /quote|quotation|pricing|price estimate|proposal/i.test(
        cleanText(ai.Purchase_intent) + " " +
        cleanText(ai.Business_need)
      );

    if (quoteRequested) {
      return "Send Pricing Information";
    }

    return "Schedule Meeting";
  }

  if (aiAction === "Request More Information") {
    return "Request More Information";
  }

  if (aiAction === "Schedule Meeting") {
    return "Schedule Meeting";
  }

  if (aiAction === "Follow Up Later") {
    return "Schedule Meeting";
  }

  return "Follow Up Later";
}

// --------------------------------------------------
// 12. RECOMMENDED ACTION MAPPING
// --------------------------------------------------

function getRecommendedAction(nextActionType) {
  const recommendedActionMap = {
    "Schedule Meeting":
      "Arrange a discovery meeting to understand the detailed project scope.",

    "Contact Immediately":
      "Contact the lead immediately to discuss the urgent requirement.",

    "Send Pricing Information":
      "Prepare and send pricing information after confirming the defined scope.",

    "Request More Information":
      "Request the missing information needed to assess the requirement.",

    "Follow Up Later":
      "Revisit the lead at an appropriate future date.",

    "Do Not Pursue":
      "Do not pursue this lead because the requested service is not a suitable match.",
  };

  return recommendedActionMap[nextActionType] ??
    "Revisit the lead at an appropriate future date.";
}

// --------------------------------------------------
// 13. FOLLOW-UP MESSAGE RULES
// --------------------------------------------------

function createFallbackMessage(
  original,
  nextAction
) {
  const name = cleanText(original.Name) || "there";
  const service = cleanText(original.Service) || "our solutions";

  if (nextAction === "Do Not Pursue") {
    return "";
  }

  if (nextAction === "Request More Information") {
    return (
      `Hello ${name}, thank you for contacting Techno Enterprises. ` +
      `To understand your requirements better, could you please share ` +
      `a few additional details about your project?`
    );
  }

  if (nextAction === "Contact Immediately") {
    return (
      `Hello ${name}, thank you for reaching out to Techno Enterprises. ` +
      `We would like to discuss your requirements for ${service} as soon as possible.`
    );
  }

  if (nextAction === "Schedule Meeting") {
    return (
      `Hello ${name}, thank you for your interest in Techno Enterprises. ` +
      `We would be happy to discuss your requirements for ${service}. ` +
      `Are you available for a brief discovery meeting?`
    );
  }

  if (nextAction === "Send Pricing Information") {
    return (
      `Hello ${name}, thank you for your inquiry. ` +
      `We would be happy to discuss the pricing for your requirements.`
    );
  }

  return (
    `Hello ${name}, thank you for sharing your requirements with Techno Enterprises. ` +
    `We have noted your interest in ${service} and can reconnect at a more suitable time.`
  );
}

// --------------------------------------------------
// 14. PROCESS AI RECORDS
// --------------------------------------------------

const processedLeadIds = new Set();
const results = [];

for (const ai of aiRecords) {
  const aiId = normalizeId(ai.Lead_id);

  if (!aiId) {
    throw new Error(
      "An AI record has a missing Lead_id."
    );
  }

  if (processedLeadIds.has(aiId)) {
    throw new Error(
      `Duplicate AI Lead_id found: ${aiId}`
    );
  }

  processedLeadIds.add(aiId);

  const original = originalMap.get(aiId);

  if (!original) {
    throw new Error(
      `AI Lead_id ${aiId} does not exist in the original Aggregate records.`
    );
  }

  validateAISchema(ai, aiId);

  // ----------------------------------------------
  // 14A. BASIC IDENTITY VALIDATION
  // ----------------------------------------------

  if (
    normalizeId(ai.Lead_id) !==
    normalizeId(original["Lead ID"])
  ) {
    throw new Error(
      `Lead ID mismatch for ${aiId}.`
    );
  }

  if (
    Number(ai.row_number) !==
    Number(original.row_number)
  ) {
    throw new Error(
      `Row number mismatch for ${aiId}. ` +
      `AI: ${ai.row_number}; CRM: ${original.row_number}.`
    );
  }

  if (
    normalizeComparable(ai.Client_name) !==
    normalizeComparable(original.Name)
  ) {
    throw new Error(
      `Client name mismatch for ${aiId}.`
    );
  }

  if (
    normalizeComparable(ai.Company) !==
    normalizeComparable(original.Company)
  ) {
    throw new Error(
      `Company mismatch for ${aiId}.`
    );
  }

  if (
    normalizeComparable(ai.Service) !==
    normalizeComparable(original.Service)
  ) {
    throw new Error(
      `Service mismatch for ${aiId}.`
    );
  }

  // Intent is not required in the AI schema.
  // The original CRM does not have an Intent column,
  // so no CRM Intent comparison is performed.

  if (
    normalizeComparable(ai.Data_Validation_Status) !==
    normalizeComparable(original["Data Validation Status"])
  ) {
    throw new Error(
      `Data Validation Status mismatch for ${aiId}.`
    );
  }

  // ----------------------------------------------
  // 14B. TEXT FIELD VALIDATION
  // ----------------------------------------------

  const requiredTextFields = [
    "Business_need",
    "Purchase_intent",
    "Qualification_reasoning",
    "AI_Analysis",
    "Score_Explanation",
    "Qualification_Reason",
    "Recommended_Action",
    "Next_Action_Type",
    "Follow_Up_Message",
  ];

  for (const field of requiredTextFields) {
    if (
      ai[field] !== null &&
      typeof ai[field] !== "string"
    ) {
      throw new Error(
        `${field} must be text or null for ${aiId}.`
      );
    }
  }

  // ----------------------------------------------
  // 14C. AI COMPONENT SCORE VALIDATION
  // ----------------------------------------------

  const purchaseIntentPoints = clampInteger(
    ai.Purchase_Intent_Points,
    0,
    AI_COMPONENT_MAX_POINTS.Purchase_Intent_Points,
    "Purchase_Intent_Points"
  );

  const businessNeedPoints = clampInteger(
    ai.Business_Need_Points,
    0,
    AI_COMPONENT_MAX_POINTS.Business_Need_Points,
    "Business_Need_Points"
  );

  // ----------------------------------------------
  // 14D. ORIGINAL BUDGET AND ESTIMATED PRICE
  // ----------------------------------------------

  const budget = parseNumber(original.Budget);

  if (
    isNonEmpty(original.Budget) &&
    budget === null
  ) {
    throw new Error(
      `Invalid original CRM Budget for ${aiId}: ${original.Budget}`
    );
  }

  if (budget !== null && budget < 0) {
    throw new Error(
      `Original CRM Budget cannot be negative for ${aiId}.`
    );
  }

  const estimatedPrice = parseNumber(
    ai.Estimated_Project_Price
  );

  if (
    isNonEmpty(ai.Estimated_Project_Price) &&
    estimatedPrice === null
  ) {
    throw new Error(
      `Invalid Estimated_Project_Price for ${aiId}: ` +
      `${ai.Estimated_Project_Price}`
    );
  }

  if (
    estimatedPrice !== null &&
    estimatedPrice <= 0
  ) {
    throw new Error(
      `Estimated_Project_Price must be positive for ${aiId}.`
    );
  }

  // ----------------------------------------------
  // 14E. DETERMINISTIC SCORING
  // ----------------------------------------------

  const budgetPoints = calculateBudgetPoints(
    budget,
    estimatedPrice
  );

  // Classify urgency before calculating the score.
  const finalUrgency = classifyFinalUrgency(
    original,
    ai
  );

  const urgencyPoints = calculateUrgencyPoints(
    finalUrgency
  );

  const serviceFit = normalizeServiceFit(
    ai.Service_Fit
  );

  const serviceFitPoints = calculateServiceFitPoints(serviceFit);

  const timelinePoints = calculateTimelinePoints(original.Timeline);

  // Preserve the customer's original timeline wording.
  const timelineClarity =        generateTimelineClarity(original.Timeline);

  const totalScore =
    budgetPoints +
    purchaseIntentPoints +
    urgencyPoints +
    businessNeedPoints +
    serviceFitPoints +
    timelinePoints;

  if (totalScore < 0 || totalScore > 100) {
    throw new Error(
      `Calculated score out of range for ${aiId}: ${totalScore}`
    );
  }

  // ----------------------------------------------
  // 14F. CATEGORY / QUALIFICATION / PRIORITY
  // ----------------------------------------------

  const leadCategory = calculateLeadCategory(
    totalScore
  );

  const qualificationStatus = calculateQualification(
    totalScore,
    leadCategory,
    original["Data Validation Status"],
    serviceFit
  );

  const priority = calculatePriority(
    qualificationStatus,
    leadCategory
  );

  const budgetSuitability = calculateBudgetSuitability(
    budgetPoints
  );

  // ----------------------------------------------
  // 14G. MISSING INFORMATION
  // ----------------------------------------------

  const missingInformation = hasMissingInformation(
    original
  );

  // ----------------------------------------------
  // 14H. FINAL NEXT ACTION
  // ----------------------------------------------

  const nextAction = determineNextAction(
    ai,
    qualificationStatus,
    serviceFit,
    missingInformation,
    finalUrgency
  );

  const recommendedAction = getRecommendedAction(
    nextAction
  );

  // ----------------------------------------------
  // 14I. FOLLOW-UP MESSAGE
  // ----------------------------------------------

  let followUpMessage = cleanText(
    ai.Follow_Up_Message
  );

  if (
    !followUpMessage ||
    nextAction !== cleanText(ai.Next_Action_Type)
  ) {
    followUpMessage = createFallbackMessage(
      original,
      nextAction
    );
  }

  if (nextAction === "Do Not Pursue") {
    followUpMessage = "";
  }

  // ----------------------------------------------
  // 14J. FOLLOW-UP ELIGIBILITY
  // ----------------------------------------------

  const validEmail = isValidEmail(original.Email);

  const actionAllowsFollowUp = [
    "Contact Immediately",
    "Schedule Meeting",
    "Request More Information",
    "Send Pricing Information",
  ].includes(nextAction);

  const sendFollowUp =
    actionAllowsFollowUp &&
    validEmail &&
    Boolean(followUpMessage);

  // ----------------------------------------------
  // 14K. SCORE EXPLANATION
  // ----------------------------------------------

  const scoreExplanation =
    `Budget: ${budgetPoints}/20; ` +
    `Purchase Intent: ${purchaseIntentPoints}/25; ` +
    `Urgency: ${urgencyPoints}/15; ` +
    `Business Need: ${businessNeedPoints}/15; ` +
    `Service Fit: ${serviceFitPoints}/15; ` +
    `Timeline: ${timelinePoints}/10. ` +
    `Total: ${totalScore}/100.`;

  // ----------------------------------------------
  // 14L. QUALIFICATION REASON
  // ----------------------------------------------

  let qualificationReason;

  if (serviceFit === "No Match") {
    qualificationReason =
      "The requested service is not a suitable match for the business.";
  } else if (qualificationStatus === "Qualified") {
    qualificationReason =
      `The lead has a score of ${totalScore}, meets the qualification ` +
      `threshold of ${QUALIFICATION_THRESHOLD}, and has valid original CRM data.`;
  } else if (
    normalizeComparable(original["Data Validation Status"]) !== "valid"
  ) {
    qualificationReason =
      "The original CRM data validation status is not Valid.";
  } else {
    qualificationReason =
      `The lead has a score of ${totalScore}, which is below the ` +
      `qualification threshold of ${QUALIFICATION_THRESHOLD}.`;
  }

  // ----------------------------------------------
  // 14M. SCORE VALIDATION AUDIT
  // ----------------------------------------------

  const originalAIScore = parseNumber(
    ai.Total_Lead_Score
  );

  const originalScoreDifference =
    originalAIScore === null
      ? null
      : totalScore - originalAIScore;

  const scoreValidationStatus =
    originalAIScore === totalScore
      ? "Passed"
      : "Corrected by code";

  // ----------------------------------------------
  // 14N. FINAL CRM OUTPUT
  // ----------------------------------------------

  const output = {
    ...original,

    // AI analysis
    "AI Analysis": cleanText(ai.AI_Analysis),
    "Service Fit": serviceFit,
    "Timeline Clarity": timelineClarity,
    "Purchase Intent": cleanText(ai.Purchase_intent),
    "Business Need": cleanText(ai.Business_need),

    // Final classified urgency
    "Urgency": finalUrgency,

    // Deterministic scoring
    "Lead Score": totalScore,
    "Lead Score Explanation": scoreExplanation,
    "Budget Points": budgetPoints,
    "Purchase Intent Points": purchaseIntentPoints,
    "Urgency Points": urgencyPoints,
    "Business Need Points": businessNeedPoints,
    "Service Fit Points": serviceFitPoints,
    "Timeline Points": timelinePoints,

    // Price and budget
    "Estimated Project Price": estimatedPrice,
    "Budget Suitability": budgetSuitability,

    // Final qualification
    "Lead Category": leadCategory,
    "Qualification Status": qualificationStatus,
    "Qualification Reason": qualificationReason,
    "Priority": priority,

    // Final recommended action and next action
    "Recommended Action": recommendedAction,
    "Next Action Type": nextAction,
    "Follow up Message": followUpMessage,

    // Follow-up control
    "Send Follow Up": sendFollowUp,

    // Score audit
    "Score Validation Status": scoreValidationStatus,
    "Original AI Score": originalAIScore,
    "Original AI Score Difference": originalScoreDifference,

    // Preserve original CRM status
    "Status of Lead": original["Status"],
  };

  results.push({ json: output });
}

// --------------------------------------------------
// 15. FINAL RECORD COMPLETENESS CHECK
// --------------------------------------------------

if (processedLeadIds.size !== originalRecords.length) {
  const missingIds = originalRecords
    .map(record => normalizeId(record["Lead ID"]))
    .filter(id => !processedLeadIds.has(id));

  throw new Error(
    `Not all original CRM records were processed. ` +
    `Missing Lead IDs: ${missingIds.join(", ")}`
  );
}

if (results.length !== originalRecords.length) {
  throw new Error(
    `Final output count mismatch. Expected ${originalRecords.length}; ` +
    `received ${results.length}.`
  );
}

return results;

