// ------------------------------------------------------
// 2. GENERAL HELPER FUNCTIONS
// ------------------------------------------------------

function normalizeKey(value) {
    return String(value ?? '')
        .toLowerCase()
        .replace(/[^a-z0-9]/g, '');
}

function cleanText(value) {
    if (value === null || value === undefined) {
        return '';
    }

    return String(value)
        .trim()
        .replace(/\s+/g, ' ');
}

function normalizeText(value) {
    return cleanText(value)
        .toLowerCase()
        .replace(/\s+/g, ' ');
}

function toProperCase(value) {
    return cleanText(value)
        .toLowerCase()
        .replace(
            /(^|[\s.'’-])(\p{L})/gu,
            (match, separator, letter) =>
                separator + letter.toUpperCase()
        );
}

function getKey(obj, possibleNames) {
    if (!obj || typeof obj !== 'object') {
        return null;
    }

    const keys = Object.keys(obj);

    for (const name of possibleNames) {
        const normalizedName = normalizeKey(name);

        const matchingKey = keys.find(
            key => normalizeKey(key) === normalizedName
        );

        if (matchingKey !== undefined) {
            return matchingKey;
        }
    }

    return null;
}

function getValue(obj, possibleNames) {
    const key = getKey(obj, possibleNames);

    return key === null ? undefined : obj[key];
}

function setValue(obj, possibleNames, value, preferredName) {
    const existingKey = getKey(obj, possibleNames);

    obj[existingKey ?? preferredName] = value;
}

function isBlank(value) {
    return (
        value === null ||
        value === undefined ||
        cleanText(value) === ''
    );
}

function isSpreadsheetError(value) {
    return /^#(ERROR|N\/A|VALUE|REF|DIV\/0|NAME|NUM|NULL)/i
        .test(cleanText(value));
}

function uniqueMessages(messages) {
    return [...new Set(
        messages
            .map(message => cleanText(message))
            .filter(Boolean)
    )];
}

function getRowNumber(lead) {
    const value = getValue(lead, [
        'row_number',
        'row number',
        'Row Number'
    ]);

    if (isBlank(value)) {
        return null;
    }

    const number = Number(value);

    return Number.isInteger(number) && number > 0
        ? number
        : null;
}

function parseList(value, separator) {
    const text = cleanText(value);

    if (!text || text.toLowerCase() === 'none') {
        return [];
    }

    return text
        .split(separator)
        .map(part => cleanText(part))
        .filter(Boolean);
}


