// ------------------------------------------------------

function validateTimeline(value) {
    const timeline = normalizeText(value)
        .replace(/[–—]/g, '-');

    if (!timeline) {
        return {
            valid: false,
            error: 'Timeline is required'
        };
    }

    const acceptedTimelines = new Set([
        'immediately',
        'asap',
        'as soon as possible',
        'urgent',
        '3 days',
        'within 3 days',
        '1 week',
        'within 1 week',
        '2 weeks',
        'within 2 weeks',
        '1 month',
        'within 1 month',
        '2 months',
        'within 2 months',
        '3 months',
        'within 3 months',
        '6 months',
        'within 6 months',
        '2-3 months',
        'within 2-3 months',
        '3-6 months',
        'within 3-6 months',
        'flexible',
        'within flexible timeline'
    ]);

    if (!acceptedTimelines.has(timeline)) {
        return {
            valid: false,
            error: 'Invalid or unspecified timeline'
        };
    }

    return {
        valid: true,
        error: null
    };
}


// ------------------------------------------------------
// 8B. TIMELINE CLARITY GENERATION
// ------------------------------------------------------

function generateTimelineClarity(value) {
    const timeline = normalizeText(value)
        .replace(/[–—]/g, '-');

    if (!timeline) {
        return 'Missing or unclear';
    }

    // Flexible timelines
    if (
        /\b(flexible|no rush|whenever convenient|no fixed deadline|flexible timeline)\b/i
            .test(timeline)
    ) {
        return 'Flexible';
    }

    // Explicitly more than one month
    if (
        /\b(more than|over|greater than|longer than|above)\s+(?:one|1)\s+months?\b/i
            .test(timeline)
    ) {
        return 'Long-term';
    }

    // Immediate expressions
    if (
        /\b(immediately|asap|as soon as possible|right away|at once|urgent)\b/i
            .test(timeline)
    ) {
        return 'Short-term';
    }

    // Extract numeric timeframe or range.
    // For a range, use the upper end of the range.

    const rangeMatch = timeline.match(
        /(\d+)\s*(?:-|to)\s*(\d+)\s*(days?|weeks?|months?|years?)/
    );

    let amount;
    let unit;

    if (rangeMatch) {
        amount = Number(rangeMatch[2]);
        unit = rangeMatch[3].toLowerCase();
    } else {
        const durationMatch = timeline.match(
            /(\d+)\s*(days?|weeks?|months?|years?)/
        );

        if (durationMatch) {
            amount = Number(durationMatch[1]);
            unit = durationMatch[2].toLowerCase();
        } else {
            // Common word-based expressions

            if (
                /\b(within a week|in a week|next week)\b/i
                    .test(timeline)
            ) {
                return 'Short-term';
            }

            if (
                /\b(within a month|in a month)\b/i
                    .test(timeline)
            ) {
                return 'Medium-term';
            }

            if (
                /\b(next few days)\b/i.test(timeline)
            ) {
                return 'Short-term';
            }

            if (
                /\b(next few weeks)\b/i.test(timeline)
            ) {
                return 'Medium-term';
            }

            if (
                /\b(next few months)\b/i.test(timeline)
            ) {
                return 'Long-term';
            }

            return 'Needs review';
        }
    }

    // Convert timeframe into approximate days.

    let days;

    if (unit.startsWith('day')) {
        days = amount;
    } else if (unit.startsWith('week')) {
        days = amount * 7;
    } else if (unit.startsWith('month')) {
        days = amount * 30;
    } else {
        days = amount * 365;
    }

    if (days <= 7) {
        return 'Short-term';
    }

    if (days <= 30) {
        return 'Medium-term';
    }

    return 'Long-term';
}


// ------------------------------------------------------
// 9. REQUIREMENT VALIDATION
// ------------------------------------------------------

function validateRequirement(value) {
    const requirement = cleanText(value);

    if (!requirement) {
        return {
            valid: false,
            error: 'Requirement is required'
        };
    }

    if (/^\d+$/.test(requirement)) {
        return {
            valid: false,
            error: 'Requirement cannot contain only numbers'
        };
    }

    if (
        /\b(asdf|qwerty|zxcv|xxxxx)\b/i.test(requirement) ||
        /^(test|testing|dummy|sample|lorem ipsum)$/i.test(requirement)
    ) {
        return {
            valid: false,
            error: 'Requirement contains placeholder or test text'
        };
    }

    const letterCount = (
        requirement.match(/\p{L}/gu) || []
    ).length;

    if (letterCount < 3) {
        return {
            valid: false,
            error: 'Requirement is too short or invalid'
        };
    }

    return {
        valid: true,
        error: null
    };
}


// ------------------------------------------------------
// 10. LEAD ID GENERATION AND DUPLICATE CHECKING
// ------------------------------------------------------

function normalizeLeadID(value) {
    return cleanText(value).toUpperCase();
}

function generateLeadID(usedIDs) {
    let id;

    do {
        id = String(
            Math.floor(
                100000000000 +
                Math.random() * 900000000000
            )
        );
    } while (usedIDs.has(id));

    usedIDs.add(id);

    return id;
}


// A. Build CRM map: Lead ID → spreadsheet row numbers.

const crmIDMap = new Map();

for (const crmItem of crmItems) {
    const crm = crmItem.json || {};

    const id = normalizeLeadID(
        getValue(crm, [
            'Lead ID',
            'Lead_id',
            'Lead ID Number'
        ])
    );

    if (!id) {
        continue;
    }

    const row = getRowNumber(crm);

    if (row === null) {
        throw new Error(
            'CRM record with Lead ID "' + id +
            '" has no valid row_number. ' +
            'Cannot safely process Lead ID duplicates.'
        );
    }

    if (!crmIDMap.has(id)) {
        crmIDMap.set(id, []);
    }

    crmIDMap.get(id).push(row);
}


// B. Determine the earliest CRM row owning each ID.

const ownerRowByID = new Map();

for (const [id, rows] of crmIDMap.entries()) {
    const uniqueRows = [...new Set(rows)];

    if (uniqueRows.length !== rows.length) {
        throw new Error(
            'CRM returned repeated row_number values for Lead ID "' +
            id + '". Check the Get row(s) in sheet output.'
        );
    }

    ownerRowByID.set(id, Math.min(...rows));
}


// C. Identify IDs repeated within incoming batch.

const batchIDEntries = new Map();
const incomingRowNumbers = new Set();

for (let index = 0; index < items.length; index++) {
    const lead = items[index].json || {};

    const row = getRowNumber(lead);

    if (row === null) {
        throw new Error(
            'Incoming invalid lead at item ' + index +
            ' has no valid row_number. ' +
            'Cannot safely update the correct Google Sheets row.'
        );
    }

    if (incomingRowNumbers.has(row)) {
        throw new Error(
            'More than one incoming item has row_number ' + row +
            '. Cannot safely update duplicate spreadsheet rows.'
        );
    }

    incomingRowNumbers.add(row);

    const id = normalizeLeadID(
        getValue(lead, [
            'Lead ID',
            'Lead_id',
            'Lead ID Number'
        ])
    );

    if (!id) {
        continue;
    }

    if (!batchIDEntries.has(id)) {
        batchIDEntries.set(id, []);
    }

    batchIDEntries.get(id).push({
        index,
        rowNumber: row
    });
}


// D. Determine earliest incoming row for new IDs.

const batchOwnerRowByID = new Map();

for (const [id, entries] of batchIDEntries.entries()) {
    if (crmIDMap.has(id) || entries.length === 1) {
        continue;
    }

    const rows = entries.map(entry => entry.rowNumber);

    if (new Set(rows).size !== rows.length) {
        throw new Error(
            'Repeated incoming Lead ID "' + id +
            '" has conflicting records with the same row_number.'
        );
    }

    batchOwnerRowByID.set(id, Math.min(...rows));
}


// E. Reserve original IDs.

const usedIDs = new Set(crmIDMap.keys());

for (const id of batchIDEntries.keys()) {
    usedIDs.add(id);
}


// ------------------------------------------------------
// 11. PROCESS INVALID LEADS
// ------------------------------------------------------

const results = [];

for (let index = 0; index < items.length; index++) {
    const item = items[index];
    const lead = { ...item.json };

    const errors = [];
    const missingInformation = [];

    const rowNumber = getRowNumber(lead);


    // A. READ ORIGINAL FIELDS

    let name = cleanText(
        getValue(lead, ['Name', 'Client Name', 'Client_name'])
    );

    let email = cleanText(
        getValue(lead, ['Email', 'Email Address'])
    );

    let service = cleanText(
        getValue(lead, ['Service', 'Required Service'])
    );

    let budget = cleanText(
        getValue(lead, ['Budget', 'Project Budget'])
    );

    const originalTimeline = getValue(
        lead,
        ['Timeline', 'Project Timeline']
    );

    let timeline = cleanText(originalTimeline);

    let requirement = cleanText(
        getValue(lead, [
            'Requirement',
            'Project Requirement',
            'Business Requirement'
        ])
    );

    let company = cleanText(
        getValue(lead, ['Company', 'Company Name'])
    );

    let phone = cleanText(
        getValue(lead, ['Phone', 'Phone Number', 'Mobile'])
    );

    let industry = cleanText(
        getValue(lead, ['Industry', 'Business Industry'])
    );

    let source = cleanText(
        getValue(lead, ['Source', 'Lead Source'])
    );

    let createdDate = cleanText(
        getValue(lead, ['Created Date', 'Date Created'])
    );


    // B. PRESERVE PREVIOUS VALIDATION INFORMATION

    const previousNotes = parseList(
        getValue(lead, ['Validation Notes']),
        ';'
    );

    const previousMissing = parseList(
        getValue(lead, ['Missing Information']),
        ','
    );

    errors.push(...previousNotes);
    missingInformation.push(...previousMissing);


    // C. STANDARDIZE TEXT FIELDS

    name = toProperCase(name);
    company = cleanText(company);
    timeline = cleanText(originalTimeline);
    requirement = cleanText(requirement);
    email = email.toLowerCase();

    service = standardizeMap(service, serviceMap);
    industry = standardizeMap(industry, industryMap);
    source = standardizeMap(source, sourceMap);


    // D. REQUIRED FIELD CHECKS

    const requiredFields = [
        { name: 'Name', value: name },
        { name: 'Email', value: email },
        { name: 'Service', value: service },
        { name: 'Budget', value: budget },
        { name: 'Timeline', value: timeline },
        { name: 'Requirement', value: requirement }
    ];

    for (const field of requiredFields) {
        if (isBlank(field.value)) {
            missingInformation.push(field.name);
            errors.push(field.name + ' is required');
        }
    }


    // E. NAME VALIDATION

    if (name) {
        const nameRegex =
            /^[\p{L}\p{M}]+(?:[\s.'’-][\p{L}\p{M}]+)*$/u;

        if (!nameRegex.test(name)) {
            errors.push('Invalid name format');
        }
    }


    // F. EMAIL VALIDATION

    const emailResult = validateEmail(email);

    email = emailResult.value;

    if (!emailResult.valid && emailResult.error) {
        errors.push(emailResult.error);
    }


    // G. SERVICE VALIDATION

    const supportedServices = [
        'AI Automation',
        'AI Agents',
        'Agentic AI'
    ];

    if (
        service &&
        !supportedServices.includes(service)
    ) {
        errors.push('Unsupported service');
    }


    // H. BUDGET VALIDATION

    const budgetResult = standardizeBudget(budget);

    budget = budgetResult.value;

    if (!budgetResult.valid && budgetResult.error) {
        errors.push(budgetResult.error);

        if (isBlank(budget)) {
            missingInformation.push('Budget');
        }
    }


    // I. PHONE VALIDATION (OPTIONAL)

    const phoneResult = standardizePhone(phone);

    phone = phoneResult.value;

    if (!phoneResult.valid && phoneResult.error) {
        errors.push(phoneResult.error);
    }


    // J. TIMELINE VALIDATION

    const timelineResult = validateTimeline(timeline);

    if (!timelineResult.valid && timelineResult.error) {
        errors.push(timelineResult.error);

        if (isBlank(timeline)) {
            missingInformation.push('Timeline');
        }
    }


    // K. REQUIREMENT VALIDATION

    const requirementResult =
        validateRequirement(requirement);

    if (
        !requirementResult.valid &&
        requirementResult.error
    ) {
        errors.push(requirementResult.error);

        if (isBlank(requirement)) {
            missingInformation.push('Requirement');
        }
    }


    // L. CREATED DATE VALIDATION

    const dateResult = standardizeDate(createdDate);

    createdDate = dateResult.value;

    if (!dateResult.valid && dateResult.error) {
        errors.push(dateResult.error);
    }


    // M. LEAD ID VALIDATION

    const originalLeadID = cleanText(
        getValue(lead, [
            'Lead ID',
            'Lead_id',
            'Lead ID Number'
        ])
    );

    const normalizedOriginalID =
        normalizeLeadID(originalLeadID);

    let leadID = originalLeadID;
    let leadIDStatus = 'Valid';

    if (!normalizedOriginalID) {
        leadID = generateLeadID(usedIDs);
        leadIDStatus = 'Generated';

    } else {
        const crmRowsForID =
            crmIDMap.get(normalizedOriginalID) || [];

        const batchEntries =
            batchIDEntries.get(normalizedOriginalID) || [];

        let mustReplace = false;
        let replacementReason = '';

        if (crmRowsForID.length > 0) {
            const ownerRow =
                ownerRowByID.get(normalizedOriginalID);

            if (rowNumber !== ownerRow) {
                mustReplace = true;

                replacementReason =
                    crmRowsForID.length > 1
                        ? 'Duplicate Replaced'
                        : 'Conflict Replaced';
            }

        } else if (batchEntries.length > 1) {
            const ownerRow =
                batchOwnerRowByID.get(normalizedOriginalID);

            if (rowNumber !== ownerRow) {
                mustReplace = true;
                replacementReason = 'Duplicate Replaced';
            }
        }

        if (mustReplace) {
            leadID = generateLeadID(usedIDs);
            leadIDStatus = replacementReason;

        } else {
            leadID = originalLeadID;
            leadIDStatus = 'Valid';

            usedIDs.add(normalizedOriginalID);
        }
    }

    usedIDs.add(normalizeLeadID(leadID));


    // N. UPDATE STANDARDIZED ORIGINAL FIELDS

    setValue(
        lead,
        ['Name', 'Client Name', 'Client_name'],
        name,
        'Name'
    );

    setValue(
        lead,
        ['Email', 'Email Address'],
        email,
        'Email'
    );

    setValue(
        lead,
        ['Service', 'Required Service'],
        service,
        'Service'
    );

    setValue(
        lead,
        ['Budget', 'Project Budget'],
        budget,
        'Budget'
    );

    // Preserve the customer's original Timeline.
    // Do not replace it with a cleaned or AI-generated value.

    setValue(
        lead,
        ['Timeline', 'Project Timeline'],
        originalTimeline ?? '',
        'Timeline'
    );

    setValue(
        lead,
        [
            'Requirement',
            'Project Requirement',
            'Business Requirement'
        ],
        requirement,
        'Requirement'
    );

    setValue(
        lead,
        ['Company', 'Company Name'],
        company,
        'Company'
    );

    setValue(
        lead,
        ['Phone', 'Phone Number', 'Mobile'],
        phone,
        'Phone'
    );

    setValue(
        lead,
        ['Industry', 'Business Industry'],
        industry,
        'Industry'
    );

    setValue(
        lead,
        ['Source', 'Lead Source'],
        source,
        'Source'
    );

    setValue(
        lead,
        ['Created Date', 'Date Created'],
        createdDate,
        'Created Date'
    );

    setValue(
        lead,
        ['Lead ID', 'Lead_id', 'Lead ID Number'],
        leadID,
        'Lead ID'
    );

    lead['Lead ID Status'] = leadIDStatus;


    // O. VALIDATION STATUS AND NOTES

    const finalErrors = uniqueMessages(errors);

    const finalMissingInformation =
        uniqueMessages(missingInformation);

    lead['Data Validation Status'] = 'Invalid';

    lead['Missing Information'] =
        finalMissingInformation.length > 0
            ? finalMissingInformation.join(', ')
            : 'None';

    lead['Validation Notes'] =
        finalErrors.length > 0
            ? finalErrors.join('; ')
            : 'Lead requires review because it entered the Invalid Leads branch';


    // P. REVIEW FIELDS

    lead['Budget Suitability'] = 'Unknown';

    lead['Purchase Intent'] = 'Needs Review';

    lead['Urgency'] = 'Needs Review';

    lead['Business Need'] =
        requirement
            ? 'Provided - Requires Review'
            : 'Unspecified';

    lead['Service Fit'] = 'Needs Review';

    // Generate Timeline Clarity from the original
    // customer-provided Timeline.

    lead['Timeline Clarity'] =
        generateTimelineClarity(originalTimeline);


    // Q. QUALIFICATION FIELDS

    lead['Lead Score'] = null;

    lead['Lead Score Explanation'] =
        'Not evaluated — invalid lead data. AI qualification was intentionally skipped.';

    lead['Lead Category'] = 'Unqualified';

    lead['Qualification Status'] =
        'Needs More Information';

    lead['Qualification Reason'] =
        'Data Validation Status is Invalid. The lead requires correction of its missing or invalid information before qualification.';

    lead['Recommended Action'] =
        'Request correction of the invalid or missing lead information before proceeding with qualification.';

    lead['Priority'] = 'Low';


    // --------------------------------------------------
    // R. AI AND FOLLOW-UP FIELDS
    // --------------------------------------------------

    // AI qualification is intentionally skipped.
    lead['AI Analysis'] =
        'Skipped — invalid lead data.';


    // A. COMMON NEXT ACTION TYPE FOR ALL INVALID LEADS

    lead['Next Action Type'] =
        'Manual Data Correction';


    // B. COMMON FOLLOW-UP STATUS FOR ALL INVALID LEADS

    lead['Follow Up Status'] =
        'Not Eligible — Invalid Data';


    // C. DYNAMIC FOLLOW-UP MESSAGE

    // Build an internal instruction using the actual
    // validation errors and missing information.

    const messageParts = [];

    if (finalMissingInformation.length > 0) {
        messageParts.push(
            'Missing information: ' +
            finalMissingInformation.join(', ') + '.'
        );
    }

    if (finalErrors.length > 0) {
        messageParts.push(
            'Validation issues: ' +
            finalErrors.join('; ') + '.'
        );
    }

    let followUpMessage;

    if (messageParts.length > 0) {
        followUpMessage =
            'Manual review required. ' +
            messageParts.join(' ') +
            ' Please correct or obtain the required information before proceeding with lead qualification or customer follow-up.';
    } else {
        followUpMessage =
            'Manual review required. This lead entered the invalid-data branch. Review its information and complete validation before proceeding with qualification or customer follow-up.';
    }

    // Preserve the existing spreadsheet column spelling
    // if it already exists; otherwise use Follow Up Message.

    setValue(
        lead,
        ['Follow Up Message', 'Follow up Message'],
        followUpMessage,
        'Follow Up Message'
    );


    // S. PRESERVE ORIGINAL ROW NUMBER

    lead['row_number'] = rowNumber;


    // T. RETURN RESULT

    const outputItem = {
        json: lead
    };

    if (item.pairedItem !== undefined) {
        outputItem.pairedItem = item.pairedItem;
    }

    results.push(outputItem);
}

return results;
